\label{dfnn}
The sequence
 $$(D_{\alpha}(f)):=(D(f,\alpha;1), D(f,\alpha;2),...)$$
is called the $\alpha$-P transformation of the original function
f(x). The so-called ,,differential inverse" transform of
$D_{\alpha}(f)$ we define as
\begin{eqnarray}\label{dtmm6}
E_{\alpha}(D_{\alpha}(f)):=\sum_{k=0}^{\infty}D(f,\alpha;k)(x-x_{\alpha})^{k}
\end{eqnarray}
if the series is convergent, where $x_{\alpha}=\alpha
a+(1-\alpha)b$.

\label{remn1}
For  practical application, instead of $\widetilde{f_{\alpha}}(x)$
it is convenient to introduced $N$-term $\alpha$-parameterized
approximation of the function $\widetilde{f_{\alpha}}(x)$ which we
shall define as
\begin{eqnarray}\label{dtmmn6}
\widetilde{f}_{\alpha,N}(x):=E_{\alpha,N}(D_{\alpha}(f)):=\sum_{k=0}^{N}D(f,\alpha;k)(x-x_{\alpha})^{k}
\end{eqnarray}

\label{dtm16}
 Let $f(x)=x^{m}$, $m\in\mathbb{N}$. Then $$D(f,\alpha;k)=\left\{
\begin{array}{c}
\left( 
\begin{array}{c}
  m \\
  k \\
\end{array} 
\right)(\alpha a^{m-k}+(1-\alpha)b^{m-k}) \ \ for  \ k<m \\
 1 \ \ \ \ for \ \ \  \
k=m\\
0 \ \  \ \ for \  \ k> m
\end{array}
\right.$$

\label{dtm17}By using the definition of transform given in Eq.
(\ref{dtmm25}) we have
 \begin{eqnarray}\label{dtm18}
D(f,\alpha;k)&=&\alpha D_{a}(f;k)+m(1-\alpha)
D_{b}(f;k)\nonumber\\&=&\alpha D_{a}(gh;k)+(1-\alpha)
D_{b}(gh;k)\nonumber\\&=&\frac{\alpha}{k!}\sum\limits_{m=0}^{k}
 \left( 
\begin{array}{c}
  k \\
  m \\
\end{array} 
\right)g^{(m)}(a)h^{(k-m)}(a)+\frac{(1-\alpha)}{k!}\sum\limits_{m=0}^{k}
 \left( 
\begin{array}{c}
  k \\
  m \\
\end{array} 
\right)g^{(m)}(b)h^{(k-m)}(b)\nonumber\\&=&\sum\limits_{m=0}^{k}[\alpha
 D_{a}(g;m)D_{a}(h;k-m)+(1-\alpha)D_{b}(g;m)D_{b}(h;k-m)].
\end{eqnarray}

\label{dtmm16}(Application to boundary-value problem) Let us consider the differential equation
\begin{eqnarray}\label{dtmm17}
\ell y:= y''(x)+\mu^{2}y(x)=0, \ \ \ \ x \in [0,1],  \ \ \mu
 \in \mathbb{R}.
\end{eqnarray}
with the boundary conditions
 \begin{eqnarray}\label{dtmnm18}
 y(0)=0, \ \ \  y(1)=1.
\end{eqnarray}
Exact solution for this problem is
\begin{eqnarray}
y(x) =\frac{\sin\mu x}{\sin\mu}.
\end{eqnarray}

\label{dtmmm16}(Application to eigenvalue problems)We consider the following eigenvalue problem
\begin{eqnarray}\label{dtmmm17}
 y''+\lambda y=0, \ \ \ \ x \in [0,1]
\end{eqnarray}
 \begin{eqnarray}\label{dtmmb18}
A_{11} y(0)+A_{12} y'(0)=0 \\ \label{dtmmmb18}
 A_{21} y(1)+A_{22} y'(1)=0
\end{eqnarray}
Taking the $\alpha$-p differential transform  of both sides
(\ref{dtmmm17}) we find
\begin{eqnarray}\label{dýn17}
D(y''+\lambda y,\alpha;k)=(k+1)(k+2)D(y,\alpha;k+2)+\lambda
D(y,\alpha;k)=0.
\end{eqnarray}
Thus the following recurrence relation is obtained
\begin{eqnarray}\label{onr1}
D(y,\alpha;k+2)=-\frac{\lambda D(y,\alpha;k)}{ (k+1)(k+2)}.
\end{eqnarray}
Using definition of  $\alpha$-p differential transform we get
\begin{eqnarray}\label{oyrn2}
\widetilde{y}_{\alpha}(x)=\sum_{k=0}^{\infty}D(y,\alpha;k)(x-x_{\alpha})^{k}
\\ \label{ogrn2} \widetilde{y'}_{\alpha}(x)=\sum_{k=0}^{\infty}k
D(y,\alpha;k)(x-x_{\alpha})^{k-1}
\end{eqnarray}
Consuquently
\begin{eqnarray}\label{orrn2}
\widetilde{y}_{\alpha}(0)=\sum_{k=0}^{\infty}D(y,\alpha;k)(\alpha-1)^{k}=\sum_{k=0}^{\infty}(-1)^{k}D(y,\alpha;k)(1-\alpha)^{k}
\\ \label{orrsn2} \widetilde{y'}_{\alpha}(0)=\sum_{k=0}^{\infty}k
D(y,\alpha;k)(\alpha-1)^{k-1}=\sum_{k=0}^{\infty}(-1)^{k}k
D(y,\alpha;k)(1-\alpha)^{k-1}
\end{eqnarray}
Thus the boundary condition given in (\ref{dtmmb18}) can be
transformed as follows
\begin{eqnarray}\label{dtsmmmb18}
 A_{11} \widetilde{y}_{\alpha}(0)+A_{12} \widetilde{y'}_{\alpha}(0)
=\sum_{k=0}^{\infty}( A_{11}(\alpha-1)^{k}+k
A_{12}(\alpha-1)^{k-1})D(y,\alpha;k)=0
\end{eqnarray}
Similarly we have
\begin{eqnarray}\label{ors2}
\widetilde{y}_{\alpha}(1)=\sum_{k=0}^{\infty}D(y,\alpha;k)\alpha^{k}
\end{eqnarray}
and
\begin{eqnarray}\label{on2}
\widetilde{y'}_{\alpha}(1)=\sum_{k=0}^{\infty}k
D(y,\alpha;k)\alpha^{k-1}
\end{eqnarray}
In this case the boundary condition given in (\ref{dtmmmb18}) can be
written as follows
\begin{eqnarray}\label{mnk}
 A_{21} \widetilde{y}_{\alpha}(1)+A_{22} \widetilde{y'}_{\alpha}(1)
=\sum_{k=0}^{\infty}( A_{21}\alpha^{k}+k
A_{22}\alpha^{k-1})D(y,\alpha;k)=0
\end{eqnarray}
Let $D(y,\alpha;0)=A \ \ \ \textrm{and} \ \ \ D(y,\alpha;1)=B.$
Substituting these values in (\ref{onr1}) we have the following
recursive procedure
\begin{eqnarray}\label{mnnk}
D(y,\alpha;k)=\left\{
                \begin{array}{ll}
                  \frac{A(-\lambda)^{\ell}}{(2\ell!)},   \ \textrm{ for} \  k=2\ell \\
                  \frac{B(-\lambda)^{\ell}}{(2\ell+1)!},   \ \textrm{for} \    k=2\ell+1
                \end{array}
              \right.
\end{eqnarray}Substituting (\ref{mnnk}) in (\ref{dtsmmmb18})and (\ref{mnk}) we find
\begin{eqnarray}\label{dn8}
&&A\{\sum_{\ell=0}^{\infty}( A_{11}(\alpha-1)^{2\ell}+2\ell
A_{12}(\alpha-1)^{2\ell-1})\frac{(-\lambda)^{\ell}}{(2\ell)!}\}\nonumber\\&+&B\{\sum_{\ell=0}^{\infty}(
A_{11}(\alpha-1)^{2\ell+1}+(2\ell+1)
A_{12}(\alpha-1)^{2\ell})\frac{(-\lambda)^{\ell}}{(2\ell+1)!}\}=0
\end{eqnarray}and
\begin{eqnarray}\label{dmn8}
&& A\{\sum_{\ell=0}^{\infty}( A_{21}\alpha^{2\ell}+2\ell
A_{22}\alpha^{2\ell-1})\frac{(-\lambda)^{\ell}}{(2\ell)!}\}\nonumber\\&+&B\{\sum_{\ell=0}^{\infty}(
A_{21}\alpha^{2\ell+1}+(2\ell+1)
A_{22}\alpha^{2\ell})\frac{(-\lambda)^{\ell}}{(2\ell+1)!}\}=0.
\end{eqnarray}
respectively. In this case we have a linear system  of the equations
with respect to the variables $A$ and $B$ as
\begin{eqnarray}\label{dnnn8}
AP_{11}(\lambda)+B P_{12}(\lambda)=0 \\ \label{dmmnn8} A
P_{21}(\lambda)+B P_{22}(\lambda)=0
\end{eqnarray}
where $P_{11}(\lambda):=\sum_{\ell=0}^{\infty}(
A_{11}(\alpha-1)^{2\ell}+2\ell
A_{12}(\alpha-1)^{2\ell-1})\frac{(-\lambda)^{\ell}}{(2\ell)!},$
$P_{12}(\lambda):=\sum_{\ell=0}^{\infty}(
A_{11}(\alpha-1)^{2\ell+1}+(2\ell+1)
A_{12}(\alpha-1)^{2\ell})\frac{(-\lambda)^{\ell}}{(2\ell+1)!}$,
$P_{21}(\lambda):=\sum_{\ell=0}^{\infty}( A_{21}\alpha^{2\ell}+2\ell
A_{22}\alpha^{2\ell-1})\frac{(-\lambda)^{\ell}}{(2\ell)!}$ and
$P_{22}(\lambda):=\sum_{\ell=0}^{\infty}(
A_{21}\alpha^{2\ell+1}+(2\ell+1)
A_{22}\alpha^{2\ell})\frac{(-\lambda)^{\ell}}{(2\ell+1)!}$. Since
the system (\ref{dnnn8})-(\ref{dmmnn8}) has a nontrivial solution
for $A$ and $B$ the characteristic determinant is zero i.e.
$$P(\lambda)=\left|
    \begin{array}{cc}
      P_{11}(\lambda) & P_{12}(\lambda) \\
      P_{21}(\lambda) & P_{22}(\lambda) \\
    \end{array}
  \right|=0.
$$
Thus we have characteristic equation for eigenvalues by $\alpha$-p
DTM Now, let us find the exact eigenvalues and eigenfunctions of the
Sturm-Liouville problem (\ref{dtmmm17})-(\ref{dtmmmb18}). The
general solution of equation (\ref{dtmmmb18}) have the form
\begin{eqnarray}\label{gen}
y(x)=C\cos \mu x+ D\sin \mu x
\end{eqnarray}
where $\lambda=\mu^{2}$ and $C, D$ are arbitrary constants. Applying
the boundary conditions (\ref{dtmmm17}), (\ref{dtmmb18})  we get
 \begin{eqnarray}\label{dff}
&&A_{11} C+\mu A_{12} D=0 \\ \label{dfff} && (A_{21}\cos -\mu
A_{22}\sin \mu)C+(A_{21}\cos -\mu A_{22}\sin \mu)D=0
\end{eqnarray}
Because we cannot have $C=D=0$, this implies
 \begin{eqnarray}\label{dfm}
(A_{11}A_{21}+\mu^{2} A_{12}A_{22})\sin \mu-\mu(A_{12}A_{21}-
A_{11}A_{22})\cos \mu=0.
\end{eqnarray}
This is transcendental equation which is solved graphically. Let
$\mu=\mu_n, n\in \mathbb{N}$ are points of intersection of the
graphs of the functions
 \begin{eqnarray}\label{kl}
&&y=(A_{11}A_{21}+\mu^{2} A_{12}A_{22})\sin \mu \ \ \  \textrm{and} \\
\label{kll} &&y=\mu(A_{12}A_{21}- A_{11}A_{22})\cos \mu
\end{eqnarray}
The eigenvalues and corresponding eigenfunctions are therefore given
by
\begin{eqnarray}\label{kmm}
\lambda_n=\mu_{n}^{2} \ \   \textrm{and} \ \  y_n(x)=C_n\cos \mu_n
x+ D_n\sin \mu_n x, \ n\in \mathbb{N}.
\end{eqnarray}
Now we consider special case of the Sturm-Liouville problem
(\ref{dtmmmb18})-(\ref{dtmmm17}),
\begin{eqnarray}\label{sp}
&&y''+\lambda y=0 \\
  \label{spl}&&y(0)+y'(0)=0 \\ \label{spll}&&y(1)-y'(1)=0.
\end{eqnarray}
The eigenvalues of this problem are determined by the equation
\begin{eqnarray}\label{spp}
\tan \mu=\frac{2\mu}{1-\mu^{2}}.
\end{eqnarray}
This equation can be solved graphically by the points of
intersections of the graphs of functions
\begin{eqnarray}\label{stpp}
y=\tan \mu \ \ \textrm{and} \ \ y=\frac{2\mu}{1-\mu^{2}}
\end{eqnarray}
as shown by the sequence $(\mu_n)$ in Figure 1.

\begin{figure}
                                  
  \includegraphics[height=6cm,width=12cm]{tanx}
  \caption{ }\label{f1}
\end{figure}

The eigenvalues of the considered problem are given by
$\lambda_n=\mu_{n}^{2}$ and corresponding eigenfunctions are given
by
\begin{eqnarray}\label{sstpp}
y_n(x)=C_n\cos \mu_n x+ D_n\sin \mu_n x, \ n\in \mathbb{N}.
\end{eqnarray}
Taking the $\alpha$-p differential transform  of both sides the
equation (\ref{sp}) the following recurrence relation is obtained
\begin{eqnarray}\label{oddh}
D(y,\alpha;k+2)=-\frac{\lambda D(y,\alpha;k)}{ (k+1)(k+2)}.
\end{eqnarray}

Applying N-term $\alpha$-p differential transform  the boundary
conditions  (\ref{spl})-(\ref{spll}) are transformed as follows:
\begin{eqnarray}\label{kml}
 && \widetilde{y}_{\alpha}(0)+ \widetilde{y'}_{\alpha}(0)
=\sum_{k=0}^{N}((\alpha-1)^{k}+k (\alpha-1)^{k-1})D(y,\alpha;k)=0
\\ \label{khg}
 &&\widetilde{y}_{\alpha}(1)-\widetilde{y'}_{\alpha}(1)
=\sum_{k=0}^{N}( \alpha^{k}-k\alpha^{k-1})D(y,\alpha;k)=0
\end{eqnarray}
By using (\ref{oddh}), (\ref{kml}) and (\ref{khg}) we obtain the
following equalities (for N=6)
\begin{eqnarray}\label{dnny8}
&&
A\bigg[1+((\alpha-1)^{2}+2(\alpha-1))\frac{(-\lambda)}{2!}+((\alpha-1)^{4}+4(\alpha-1)^{3})\frac{\lambda^{2}}{4!}\nonumber\\&+&
((\alpha-1)^{6}+6(\alpha-1)^{5})\frac{(-\lambda^{3})}{6!}\bigg]+B\bigg[\alpha+((\alpha-1)^{3}+3(\alpha-1)^{2})\frac{(-\lambda)}{3!}\nonumber\\
&+&((\alpha-1)^{5}+5(\alpha-1)^{4})\frac{\lambda^{2}}{5!}\bigg]=0
\end{eqnarray}and
\begin{eqnarray}\label{dnyy8}
&&
A\bigg[1+(\alpha^{2}-2\alpha)\frac{(-\lambda)}{2!}+(\alpha^{4}-4\alpha^{3})\frac{\lambda^{2}}{4!}+
(\alpha^{6}-6\alpha^{5})\frac{(-\lambda^{3})}{6!}\bigg]\nonumber\\&+&B\bigg[(\alpha-1)+(\alpha^{3}-3\alpha^{2})\frac{(-\lambda)}{3!}+(\alpha^{5}-5\alpha^{4})\frac{\lambda^{2}}{5!}\bigg]=0
\end{eqnarray}
